  Ciphertext w = z * c2;             // c2 alpha x
  Ciphertext v = w + w + c1;         // 2 c2 z + c1
  Ciphertext p = x * v;              // x (2 c2 z + c1)
  Ciphertext q = p * alpha;          // z (2 c2 z + c1)
